import{_ as i,C as r,o as n,c as h,j as e,a as d,E as a,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"间距","description":"","frontmatter":{},"headers":[],"relativePath":"components/space.md","filePath":"components/space.md","lastUpdated":1787185306000}'),s={name:"components/space.md"},p={id:"间距",tabindex:"-1"};function u(b,t,m,x,q,f){const l=r("Badge"),o=r("XhDemo");return n(),h("div",null,[e("h1",p,[t[0]||(t[0]=d("间距 ",-1)),a(l,{type:"info",text:"space"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#间距","aria-label":'Permalink to "间距 <Badge type="info" text="space" />"'},"​",-1))]),t[3]||(t[3]=c('<p>一维排布容器：子项沿一条轴排开，两两之间按档位留白，还能在每两项之间放一份分隔符。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>一排按钮、一排标签、一列表单项这类&quot;东西挨着摆、中间要留口气&quot;的结构。</li><li>需要在相邻两项之间统一放一条竖线、一个点号这类分隔符。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>排布参数要从零调起、间距默认就是 0：用<a href="./flex">弹性布局</a>。它是通用一维容器，本组件是它上面立了默认间距与分隔符的那一档。</li><li>要排成二维网格、需要跨列：用<a href="./grid">栅格</a>。</li><li>只是想切分页面上的两块区域：用<a href="./separator">分隔线</a>，那是一条有语义的横线，不是排布容器。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>与弹性布局的分野只有两条：<code>gap</code> 缺省就是 <code>md</code>（不写也留白），以及多了一个 <code>split</code> 分隔符部件。</li><li><code>gap</code> 收的是档位名不是像素：<code>xs</code> / <code>sm</code> / <code>md</code> / <code>lg</code> / <code>xl</code> 逐档指向一个间距令牌。</li><li>缺省的交叉轴对齐随方向走：横排按中线对齐，竖排拉伸占满。写了 <code>align</code> 即以它为准。</li><li>档位不够用时给 <code>--xh-space-gap</code> 写一个值，它排在所有档位之前。<strong>它是自定义属性，会顺着继承流进嵌套在里面的每一层间距容器，把那些层的档位一并压掉</strong>；只想改一层就写在那一层上。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一排东西挨着摆：什么参数都不写也留 md 间距，这是它与弹性容器的分野</p>',10)),a(o,{src:"space/01-basic"}),t[4]||(t[4]=e("h3",{id:"方向",tabindex:"-1"},[d("方向 "),e("a",{class:"header-anchor",href:"#方向","aria-label":'Permalink to "方向"'},"​")],-1)),t[5]||(t[5]=e("p",null,"direction 换排布轴：horizontal 横排（缺省）按中线对齐，vertical 竖排拉伸占满",-1)),a(o,{src:"space/02-direction"}),t[6]||(t[6]=e("h3",{id:"分隔符",tabindex:"-1"},[d("分隔符 "),e("a",{class:"header-anchor",href:"#分隔符","aria-label":'Permalink to "分隔符"'},"​")],-1)),t[7]||(t[7]=e("p",null,"每两个子项之间放一份分隔符：Vue 交给 split 插槽自动铺，WC 由作者逐个写在 root 里",-1)),a(o,{src:"space/03-split"}),t[8]||(t[8]=e("h3",{id:"间距档位",tabindex:"-1"},[d("间距档位 "),e("a",{class:"header-anchor",href:"#间距档位","aria-label":'Permalink to "间距档位"'},"​")],-1)),t[9]||(t[9]=e("p",null,"gap 收的是档位名不是像素：xs / sm / md / lg / xl 逐档指向一个间距令牌，缺省 md",-1)),a(o,{src:"space/04-gap"}),t[10]||(t[10]=e("h3",{id:"对齐、折行与行内",tabindex:"-1"},[d("对齐、折行与行内 "),e("a",{class:"header-anchor",href:"#对齐、折行与行内","aria-label":'Permalink to "对齐、折行与行内"'},"​")],-1)),t[11]||(t[11]=e("p",null,"align 改交叉轴对齐，wrap 让放不下的子项换行、行间距同样吃 gap，inline 让容器缩到内容宽度",-1)),a(o,{src:"space/05-align-wrap"}),t[12]||(t[12]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-space&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSpace</code> <code>XhSpaceSplit</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/space.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;space&quot;</code>：<strong><code>root</code></strong> · <code>split</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>align</code></td><td><code>SpaceAlign</code></td><td></td><td>交叉轴对齐：start / center / end / stretch / baseline，不写则横排按中线对齐、竖排拉伸。</td></tr><tr><td><code>direction</code></td><td><code>Orientation</code></td><td></td><td>排布方向：horizontal 横排、vertical 竖排，缺省 horizontal。</td></tr><tr><td><code>gap</code></td><td><code>SpaceGap</code></td><td></td><td>子项间距档位：xs / sm / md / lg / xl，缺省 md。档位换算成多少由皮肤定。</td></tr><tr><td><code>inline</code></td><td><code>boolean</code></td><td></td><td>容器按行内盒排版，宽度收到内容。</td></tr><tr><td><code>justify</code></td><td><code>SpaceJustify</code></td><td></td><td>主轴分布：start / center / end / between / around / evenly，不写则子项从主轴起点排起。</td></tr><tr><td><code>wrap</code></td><td><code>boolean</code></td><td></td><td>一行放不下时折行。</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSpace</code></td><td><code>default</code></td><td>—</td><td>子项，按写进来的顺序排开。</td></tr><tr><td><code>XhSpace</code></td><td><code>split</code></td><td>—</td><td>分隔符的内容：写了它，组件在每两个子项之间各铺一个分隔符部件，逐缝重新求值一次。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSplitProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>分隔符节点。它是装饰件，恒带 aria-hidden：一排里夹着的竖线被逐条念出来只会打断内容。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>split</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>分隔符自带 <code>aria-hidden=&quot;true&quot;</code>，不必自己写：读屏逐项念过来时，中间夹一堆竖线只会打断内容。</li><li>容器根上不写 <code>role</code>：里面装的是列表还是一组按钮，由作者自己声明。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/space.css</code> 按部件选择：<code>[data-scope=&quot;space&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-align</code></td><td>props.align</td></tr><tr><td><code>root</code></td><td><code>data-gap</code></td><td>props.gap</td></tr><tr><td><code>root</code></td><td><code>data-inline</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-justify</code></td><td>props.justify</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.direction</td></tr><tr><td><code>root</code></td><td><code>data-wrap</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-space-1</code> · <code>--xh-space-2</code> · <code>--xh-space-3</code> · <code>--xh-space-4</code> · <code>--xh-space-6</code> · <code>--xh-space-gap</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><ul><li>排布走的是逻辑方向：<code>dir=&quot;rtl&quot;</code> 下横排自动从右往左，皮肤里没有物理左右。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>分隔符是一个正经部件：两端铺出来的 DOM 形状一致（<code>root</code> 底下按 <code>子项、分隔符、子项…</code> 相间排列），皮肤按 <code>split</code> 给它样式，样子由放进去的内容决定。 <ul><li>Vue：写 <code>split</code> 具名插槽，组件在每两个子项之间各铺一个分隔符部件，插槽逐缝重新求值；也可以不写插槽、自己在子项之间手写分隔符部件，两种写法铺出来的结构相同。</li><li>Web Components：元素不生成任何结构，分隔符由作者自己写在 <code>root</code> 里、夹在两个子项中间。</li></ul></li><li>与<a href="./separator">分隔线</a>配合：把一条竖向分隔线放进分隔符里，一排操作就被切成几组。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>间距一律走档位，别写具体像素：换主题时间距节奏才跟着一起变。</li><li>一排里的元素靠它排，别用外边距凑——外边距在折行时会留出多余的空白。</li><li>一排东西会被动态摘掉时（关掉一个标签、删掉一条操作），焦点交接要自己接：被摘的那一项若正持有焦点，焦点会掉回页面根上，键盘与读屏用户每摘一次就丢一次位置。本组件只管排布，不接管焦点。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>为了改一处间距就把整棵结构换成手写外边距：档位对不齐，后面每加一项都要再对一次。</li><li>把分隔符当内容用：它在每一道缝里各有一份，写进去的文字会重复很多遍，而且整个部件对读屏是隐藏的。</li></ul>',36))])}const k=i(s,[["render",u]]);export{P as __pageData,k as default};
